with valid as (select id, txn_type, amount, merchant, is_flagged, case when merchant in ('Amazon', 'Grab') then 'Priority' else 'Other' end as merchant_group, coalesce(merchant, 'UNKNOWN') as merchant_filled from transactions where txn_time >= date '2024-04-19') select * from (select txn_type, merchant, amount from valid) src pivot (max(amount) as value_sum, count(1) as n for merchant in ('Lazada', 'Starbucks'));
